import sqlite3
from collections import Counter, defaultdict
c = sqlite3.connect("file:planbench.db?mode=ro", uri=True); q = c.execute
rows = {r[0]: (r[1], r[2], r[3]) for r in q("select id, checksum, name, created_at from maps")}
anchored = set()
for t in ("simulations", "benchmarks"):
    anchored |= {r[0] for r in q(f"select distinct map_id from {t}") if r[0]}
live_scen_maps = set()
sref = set()
for t in ("simulations", "benchmarks"):
    sref |= {r[0] for r in q(f"select distinct scenario_id from {t}") if r[0]}
for sid, mid in q("select id, map_id from scenarios"):
    if sid in sref:
        live_scen_maps.add(mid)
protected = anchored | live_scen_maps

groups = defaultdict(list)
for mid, (cs, name, created) in rows.items():
    groups[cs].append(mid)

delete = []
for cs, ids in groups.items():
    keep_pool = [m for m in ids if m in protected]
    if keep_pool:
        survivors = set(keep_pool)          # every protected copy stays
    else:
        survivors = {sorted(ids, key=lambda m: rows[m][2])[0]}  # oldest stands in
    delete += [m for m in ids if m not in survivors]

print(f"maps 198 -> delete {len(delete)}, keep {198-len(delete)}")
print(f"distinct checksums before {len(groups)}, after {len({rows[m][0] for m in rows if m not in set(delete)})}")
print("\nper name (kept / deleted):")
kept = [m for m in rows if m not in set(delete)]
kc, dc = Counter(rows[m][1] for m in kept), Counter(rows[m][1] for m in delete)
for name in sorted(set(kc) | set(dc), key=lambda n: -dc.get(n, 0)):
    print(f"  {kc.get(name,0):3d} kept / {dc.get(name,0):4d} deleted   {name}")
PYEOF

